/// Journal Error trans list extension
/// </summary>
[ExtensionOf(classstr(JournalErrorTransList))]
final class METJournalErrorTransList_Extension
{
}

Method.Source:
/// <summary>
/// Add infolog extension to trigger the logs to appinsight
/// </summary>
/// <param name = "_journalCheckPost">JournalCheckPost buffer</param>
/// <param name = "_journalTransData">JournalTransData buffer</param>
/// <returns>true or false</returns>
public boolean addInfolog(JournalCheckPost _journalCheckPost, JournalTransData _journalTransData)
{
    boolean ret;

    ret = next addInfolog(_journalCheckPost, _journalTransData);

    if (InventJournalTable::find(_journalTransData.journalTrans().JournalId).METJournalLinesCount)
    {
        this.sendInventJournalHeaderInformationToAppinsights(this.infoLogMessage(journalError.Infolog), _journalTransData.journalTrans());
    }

    return ret;
}

/// <summary>
/// InfoLog Message
/// </summary>
/// <param name = "con">Container to add messages</param>
/// <returns>logMessage messages</returns>
private str infoLogMessage(container con)
{
    SysInfologEnumerator    sysInfologEnumerator;
    str                     logMessage;

    sysInfologEnumerator = SysInfologEnumerator::newData(con);

    while (sysInfologEnumerator.moveNext())
    {
        int i = 1;

        if (logMessage)
        {
            logMessage +=  METConstants::NextLine;
        }

        SysInfologMessageStruct infoMessageStruct = SysInfologMessageStruct::construct(sysInfologEnumerator.currentMessage());

        while (i <= infoMessageStruct.prefixDepth())
        {

            logMessage += infoMessageStruct.preFixTextElement(i) + '. ';
            i++;
        }

        logMessage += infoMessageStruct.message();
    }
    return logMessage;
}

/// <summary>
/// send invent journal header information to appinsights
/// </summary>
/// <param name = "_errorMessage">Error Message</param>
/// <param name = "_inventJournalTrans">Invent journal trans Buffer</param>
protected void sendInventJournalHeaderInformationToAppinsights(Notes _errorMessage, InventJournalTrans _inventJournalTrans)
{
    Notes errMsg = _errorMessage;
    TableId tableId = TableNum(InventJournalTrans);
    DictFieldGroup dictFieldGrp = new DictFieldGroup(tableId,METConstants::METReference);
    int counter;

    METTelemetryInventJournalCheckPostLogging metInventJournalCheckPostLogging = METTelemetryInventJournalCheckPostLogging::construct(Errmsg);

    // If table is having table group METReference then check all the fields and assign those fields as custom dimensions
    if (dictFieldGrp)
    {
        for (counter = 1; counter <= dictFieldGrp.numberOfFields(); counter++)
        {
            int fieldId = dictFieldGrp.field(counter);

            DictField dictField = new DictField(tableId, fieldId);
            if (_inventJournalTrans.(fieldId))
            {
                errMsg += strFmt("@MET:Multiplestrmt",dictField.label(), any2str(_inventJournalTrans.(fieldId)));
                //Reference Added as custom dimension
                metInventJournalCheckPostLogging.addRuntimeProperty(dictField.label(), any2str(_inventJournalTrans.(fieldId)));
            }
        }
    }

    metInventJournalCheckPostLogging.errmsg = errMsg;
    metInventJournalCheckPostLogging.processEvent(METApplicationInsightsEventNames::InventJournalCheckPostLog);

}
